class Solution {
  public int countShips(Sea sea, int[] topRight, int[] bottomLeft) {
    int x1 = bottomLeft[0], y1 = bottomLeft[1], x2 = topRight[0], y2 = topRight[1];
    if (x1 > x2 || y1 > y2 || !sea.hasShips(topRight, bottomLeft)) return 0;
    if (x1 == x2 && y1 == y2) return 1;
    // split into four quadrants; empty ones are pruned by hasShips
    int mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    return countShips(sea, new int[] {mx, my}, new int[] {x1, y1})
        + countShips(sea, new int[] {x2, my}, new int[] {mx + 1, y1})
        + countShips(sea, new int[] {mx, y2}, new int[] {x1, my + 1})
        + countShips(sea, new int[] {x2, y2}, new int[] {mx + 1, my + 1});
  }
}
